/// <para>
/// The field must be a <c>public static readonly</c> field of the declaring value object type, initialized with the
/// private constructor (<c>new(...)</c>) rather than <c>Create</c> - <c>Create</c> validates, and validation consults the
/// declared set that is still being built at that point. A field of any other shape is reported on first use, as is a
/// duplicate value - with one undetectable exception: a field left without an initializer (permanently null) cannot be
/// told apart from a field whose initialization is still running, so the set silently stays inactive and every creation
/// rescans. The compiler flags such a field (CS8618 / CS0649); do not leave those warnings unresolved. The user hooks
/// stay free: <c>GetDefinedInstance</c> is consulted ahead of the declared set, and an <c>OnValidate</c> runs in
/// addition to the membership check.
/// </para>
/// <para>
/// A declared instance can also claim its input notation for <c>TryCreateFrom</c> / <c>CreateFrom</c>:
/// <see cref="InputText"/> claims one exact string, and <see cref="ClaimsAbsent"/> claims the absent input, so a
/// notation like "a mark or a blank cell" closes in the declarations alone. The user hooks
/// (<c>ConvertCustomInput</c> / <c>ConvertAbsentInput</c>) are consulted first when both are present.
/// </para>
/// </remarks>
[AttributeUsage(AttributeTargets.Field)]
public sealed class DeclaredInstanceAttribute : Attribute
{
    /// <summary>A string input that TryCreateFrom / CreateFrom read as this instance, ahead of the ordinary conversion.</summary>
    /// <remarks>
    /// Matching is exact and ordinal - no trimming, no case folding, no culture - and applies to string inputs only
    /// (any other input takes the ordinary conversion, whose result still resolves to the declared instance). An empty
    /// string can never match, because an empty input is absent before the notation is consulted - declare
    /// <see cref="ClaimsAbsent"/> instead (an empty <see cref="InputText"/> is reported on first use). The same text on
    /// two fields is reported as well.
    /// </remarks>
    public string? InputText { get; set; }

    /// <summary>Claims the absent input (null, DBNull, or an empty string) for this instance in TryCreateFrom / CreateFrom.</summary>
    /// <remarks>
    /// The declarative counterpart of the <c>ConvertAbsentInput</c> hook, with the same boundary: an edit model's blank
    /// input and a database NULL are unaffected. At most one field of the type may claim it - a second one is reported
    /// on first use.
    /// </remarks>
    public bool ClaimsAbsent { get; set; }
}

/// <summary>Reflects a value object's [DeclaredInstance] fields once and answers lookup, membership and display-name queries.</summary>
/// <remarks>
/// The scan runs on the type's first creation and is cached; a type without marked fields settles into a single flag
/// check. A scan that observes a null field value ran during the type's own static initialization (a field initialized
/// with <c>Create</c> instead of the constructor), so its result is not cached and the next call scans again - an
/// incomplete set is never frozen. The trade-off: a field left without an initializer is permanently null and looks
/// exactly the same, so it cannot be reported - the set stays inactive and every creation rescans (the attribute's
/// XmlDoc points the user at the compiler warnings that flag such a field). Lookup is a linear scan over the declared
/// entries: the sets are small, and the scan keeps the hot path free of allocation without constraining the value type.
/// </remarks>
internal static class DeclaredInstanceRegistry<TSelf, TValue>
    where TSelf : ValueObjectBaseCore<TSelf, TValue>, IValueObject<TSelf, TValue>
{
    /// <summary>One declared instance: the raw value, the instance itself, the [Display] name, and the claimed input notation when present.</summary>
    private sealed class Entry
    {
        public required TValue Value { get; init; }
        public required TSelf Instance { get; init; }
        public string? Name { get; init; }
        public string? InputText { get; init; }
        public bool ClaimsAbsent { get; init; }
    }

    /// <summary>The declared entries in declaration order, or null while unscanned (or while the type's static initialization is still running).</summary>
    private static Entry[]? _entries;

    /// <summary>The declared instances handed out by All (built once from the published entries).</summary>
    private static TSelf[]? _all;

    /// <summary>True once a scan found no marked fields - the permanent fast path for an ordinary value object.</summary>
    private static bool _noDeclaredInstances;

    /// <summary>Whether TValue can hold null at all. Guards the null test below so a value-typed TValue never evaluates it - the generic "is null" boxes the value in unoptimized code, and the creation path must stay allocation-free.</summary>
    private static readonly bool _valueIsNullable = default(TValue) is null;

    /// <summary>Gets the declared instances in declaration order (empty for a type that declares none).</summary>
    internal static IReadOnlyList<TSelf> All
    {
        get
        {
            var entries = EntriesOrNull();

            if (entries is null)
            {
                return Array.Empty<TSelf>();
            }

            var all = _all;

            if (all is null)
            {
                all = new TSelf[entries.Length];

                for (var i = 0; i < entries.Length; i++)
                {
                    all[i] = entries[i].Instance;
                }

                _all = all;
            }

            return all;
        }
    }

    /// <summary>Returns the declared instance for the value, when the type declares one.</summary>
    internal static bool TryGet(TValue value, out TSelf? declared)
    {
        var entries = EntriesOrNull();

        if (entries is not null)
        {
            var comparer = EqualityComparer<TValue>.Default;

            foreach (var entry in entries)
            {
                if (comparer.Equals(entry.Value, value))
                {
                    declared = entry.Instance;
                    return true;
                }
            }
        }

        declared = null;
        return false;
    }

    /// <summary>Adds a violation when the type declares a closed set and the value is not in it (a null value is left to the required rule).</summary>
    internal static void ValidateMember(TValue value, string displayName, ref List<string>? errors)
    {
        if (_valueIsNullable && value is null)
        {
            return;
        }

        var entries = EntriesOrNull();

        if (entries is null)
        {
            return;
        }

        var comparer = EqualityComparer<TValue>.Default;

        foreach (var entry in entries)
        {
            if (comparer.Equals(entry.Value, value))
            {
                return;
            }
        }

        // A null value returned above whenever TValue can hold one (_valueIsNullable covers exactly those types),
        // so the value here is never null - the flow analysis just cannot see through the guard's flag.
        (errors ??= new List<string>()).Add(
            ValueObjectValidationMessages.ValueNotDeclared(displayName, value!)
        );
    }

    /// <summary>Returns the declared instance whose InputText matches the string input exactly (ordinal), when the type declares one.</summary>
    internal static bool TryGetForInput(string text, out TSelf? declared)
    {
        var entries = EntriesOrNull();

        if (entries is not null)
        {
            foreach (var entry in entries)
            {
                if (entry.InputText is not null && string.Equals(entry.InputText, text, StringComparison.Ordinal))
                {
                    declared = entry.Instance;
                    return true;
                }
            }
        }

        declared = null;
        return false;
    }

    /// <summary>Returns the declared instance that claims the absent input (ClaimsAbsent), when the type declares one.</summary>
    internal static bool TryGetAbsentInstance(out TSelf? declared)
    {
        var entries = EntriesOrNull();

        if (entries is not null)
        {
            foreach (var entry in entries)
            {
                if (entry.ClaimsAbsent)
                {
                    declared = entry.Instance;
                    return true;
                }
            }
        }

        declared = null;
        return false;
    }

    /// <summary>Returns the [Display] name of a declared instance (matched by value equality), or null when the instance is not declared or carries no name.</summary>
    internal static string? NameOf(TSelf instance)
    {
        var entries = EntriesOrNull();

        if (entries is not null)
        {
            foreach (var entry in entries)
            {
                if (instance.Equals(entry.Instance))
                {
                    return entry.Name;
                }
            }
        }

        return null;
    }

    /// <summary>Returns the cached entries, scanning on the first call; null means "no declared set is available right now".</summary>
    private static Entry[]? EntriesOrNull()
    {
        if (_noDeclaredInstances)
        {
            return null;
        }

        return _entries ?? Scan();
    }

    /// <summary>Scans the type's [DeclaredInstance] fields and publishes the table, or returns null without caching when the type's static initialization has not finished.</summary>
    private static Entry[]? Scan()
    {
        var fields = typeof(TSelf).GetFields(
            BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly
        );
        List<FieldInfo>? marked = null;

        foreach (var field in fields)
        {
            if (field.GetCustomAttribute<DeclaredInstanceAttribute>() is not null)
            {
                (marked ??= new List<FieldInfo>()).Add(field);
            }
        }

        if (marked is null)
        {
            _noDeclaredInstances = true;
            return null;
        }

        // A binary value object compares its value structurally, but EqualityComparer<byte[]> compares by reference,
        // so a declared set over byte[] would silently reject every re-read value. Refuse it outright.
        if (typeof(TValue) == typeof(byte[]))
        {
            throw new InvalidOperationException(
                $"[DeclaredInstance] is not supported on a binary value object ({typeof(TSelf).Name})."
            );
        }

        // Reflection does not guarantee field order; the metadata token preserves declaration order in practice.
        marked.Sort(static (a, b) => a.MetadataToken.CompareTo(b.MetadataToken));

        var entries = new Entry[marked.Count];
        var comparer = EqualityComparer<TValue>.Default;
        var absentClaimed = false;

        for (var i = 0; i < marked.Count; i++)
        {
            var field = marked[i];

            if (field.FieldType != typeof(TSelf) || !field.IsInitOnly)
            {
                throw new InvalidOperationException(
                    $"[DeclaredInstance] must mark a public static readonly {typeof(TSelf).Name} field; '{field.Name}' is not one."
                );
            }

            var attribute = field.GetCustomAttribute<DeclaredInstanceAttribute>()!;

            // An empty input text can never match: an empty input is absent before the notation is consulted.
            // Refuse the configuration instead of letting it sit there silently dead - ClaimsAbsent is what was meant.
            if (attribute.InputText is { Length: 0 })
            {
                throw new InvalidOperationException(
                    $"[DeclaredInstance] on '{typeof(TSelf).Name}.{field.Name}' declares an empty InputText, which can never match (an empty input is absent). Declare ClaimsAbsent = true instead."
                );
            }

            if (attribute.ClaimsAbsent)
            {
                if (absentClaimed)
                {
                    throw new InvalidOperationException(
                        $"The [DeclaredInstance] fields of {typeof(TSelf).Name} claim the absent input more than once ('{field.Name}' is the second)."
                    );
                }

                absentClaimed = true;
            }

            if (field.GetValue(null) is not TSelf instance)
            {
                // The type's own static initialization is still running (a field initialized with Create).
                // Publish nothing so the incomplete set is never frozen; the next call scans again.
                return null;
            }

            for (var j = 0; j < i; j++)
            {
                if (comparer.Equals(entries[j].Value, instance.Value))
                {
                    throw new InvalidOperationException(
                        $"The [DeclaredInstance] fields of {typeof(TSelf).Name} declare the value '{instance.Value}' more than once."
                    );
                }

                if (attribute.InputText is not null
                    && string.Equals(entries[j].InputText, attribute.InputText, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        $"The [DeclaredInstance] fields of {typeof(TSelf).Name} declare the InputText '{attribute.InputText}' more than once ('{field.Name}' is the second)."
                    );
                }
            }

            entries[i] = new Entry
            {
                Value = instance.Value,
                Instance = instance,
                Name = field.GetCustomAttribute<DisplayAttribute>()?.GetName(),
                InputText = attribute.InputText,
                ClaimsAbsent = attribute.ClaimsAbsent,
            };
        }

        _entries = entries;
        return entries;
    }
}

/// <summary>Common base for value objects. Provides the Create / TryCreate / Validate factories, value storage, equality, ToString, and extraction of the raw value (ordered comparison is added by derived types).</summary>
public abstract class ValueObjectBaseCore<TSelf, TValue>
    : IValueObjectCore,
        IEquatable<TSelf>,
        IFormattable
    where TSelf : ValueObjectBaseCore<TSelf, TValue>, IValueObject<TSelf, TValue>
{
    /// <summary>Gets the underlying value (never reassigned; reference-typed values such as byte[] are not defensively copied — the binary value object base states that contract).</summary>
    public TValue Value { get; }

    /// <summary>Initializes with an already-validated value (Create/TryCreate performs validation beforehand).</summary>
    protected ValueObjectBaseCore(TValue value) => Value = value;

    /// <summary>Validates and creates the value object (throws ValueObjectValidationException on violation).</summary>
    /// <remarks>
    /// An inherited static member satisfies a static abstract interface member, so this single implementation is what
    /// every derived value object exposes as <c>IValueObject&lt;TSelf, TValue&gt;.Create</c> — the type itself only
    /// supplies <c>New</c> (the constructor call) and <c>ValidateCore</c> (the rules).
    /// </remarks>
    public static TSelf Create(TValue value)
    {
        List<string>? errors = null;
        RunValidation(value, ref errors);
        if (errors is { Count: > 0 })
        {
            throw new ValueObjectValidationException(typeof(TSelf), errors);
        }
        return Materialize(value);
    }

    /// <summary>Returns true plus the value object when creation succeeds, or false plus the error details when it fails.</summary>
    public static bool TryCreate(
        TValue value,
        out TSelf? result,
        out IReadOnlyList<string> errors
    )
    {
        List<string>? list = null;
        RunValidation(value, ref list);
        if (list is { Count: > 0 })
        {
            result = null;
            errors = list;
            return false;
        }
        result = Materialize(value);
        errors = Array.Empty<string>();
        return true;
    }

    /// <summary>Runs the validation rules (ValidateCore, including the OnValidate extension where one is written, plus the [DeclaredInstance] membership check) without creating the value object, adding any violations to the given collection.</summary>
    /// <returns>True when this value passed, false when at least one violation was added. The verdict covers this call only, so it stays meaningful when the collection is shared across several values.</returns>
    public static bool Validate(TValue value, ICollection<string> errors)
    {
        List<string>? collected = null;
        RunValidation(value, ref collected);
        if (collected is null or { Count: 0 })
        {
            return true;
        }

        foreach (var error in collected)
        {
            errors.Add(error);
        }

        return false;
    }

    /// <summary>Runs the type's validation rules plus the declared-set membership check - the shared body behind Create / TryCreate / Validate.</summary>
    /// <remarks>
    /// The membership check runs in addition to <c>ValidateCore</c>, so an <c>OnValidate</c> the type wrote keeps working
    /// alongside a [DeclaredInstance] set - the two do not compete for the same extension point. A type without marked
    /// fields pays a single flag check here.
    /// </remarks>
    private static void RunValidation(TValue value, ref List<string>? errors)
    {
        TSelf.ValidateCore(value, ref errors);
        DeclaredInstanceRegistry<TSelf, TValue>.ValidateMember(value, TSelf.DisplayName, ref errors);
    }

    /// <summary>Builds the instance for an already-validated value: the declared instance when the type has one, otherwise a new one.</summary>
    /// <remarks>
    /// The single creation point behind <c>Create</c> and <c>TryCreate</c>, so an enumeration-like value object returns its
    /// declared instances on every path - the raw-SQL and materializer factories and the JSON converter all come through here.
    /// The stations run in order: the <c>GetDefinedInstance</c> hook first (a type's own lookup wins), then the
    /// [DeclaredInstance] registry, then an ordinary construction.
    /// </remarks>
    private static TSelf Materialize(TValue value)
    {
        if (TSelf.TryGetDefined(value, out var defined) && defined is not null)
        {
            return defined;
        }

        if (DeclaredInstanceRegistry<TSelf, TValue>.TryGet(value, out var declared))
        {
            return declared!;
        }

        return TSelf.New(value);
    }

    /// <summary>Gets the instances marked with [DeclaredInstance], in declaration order (empty for a type that declares none).</summary>
    /// <remarks>An inherited static member, so it reads as <c>MeasureStatusValue.GetDeclaredInstances()</c> on the concrete type - a ready-made source for a selection list.</remarks>
    public static IReadOnlyList<TSelf> GetDeclaredInstances() =>
        DeclaredInstanceRegistry<TSelf, TValue>.All;

    /// <summary>Gets the [Display(Name = ...)] of this instance when its value is declared with [DeclaredInstance] and the field carries one, otherwise null.</summary>
    /// <remarks>The one-liner for a <c>DisplayValue</c> override: <c>public override string DisplayValue =&gt; DeclaredDisplayName ?? base.DisplayValue;</c>. Matching is by value equality, so an equal-valued instance resolves the same name.</remarks>
    protected string? DeclaredDisplayName =>
        DeclaredInstanceRegistry<TSelf, TValue>.NameOf((TSelf)this);

    /// <summary>Converts a value from outside the model and creates the value object from it, without throwing (an absent value succeeds with a null result unless the type claims it).</summary>
    /// <remarks>
    /// A shape the type accepts of its own is consulted first (<see cref="IValueObject{TSelf}.TryConvertCustomInput"/>,
    /// then a declared input notation), so a
    /// custom shape is honored no matter how this method is called; an absent input is likewise offered to the type
    /// (<see cref="IValueObject{TSelf}.TryConvertAbsentInput"/>, then a ClaimsAbsent declared instance) before falling
    /// back to the null result. The conversion to
    /// the underlying type is
    /// <see cref="RawValueConverter.ConvertInput"/>, so text written for a culture is read in that culture and numeric text
    /// may carry group separators. Everything past the conversion is the ordinary <c>TryCreate</c>, so the type's own
    /// validation - and its declared instances - apply unchanged.
    /// </remarks>
    /// <param name="raw">The value read from the source.</param>
    /// <param name="provider">The culture the text is written in; <c>null</c> uses the invariant culture.</param>
    /// <param name="result">The value object, or null when the value was absent (and not claimed) or could not be created.</param>
    /// <param name="errors">The violations, empty when the call succeeded.</param>
    public static bool TryCreateFrom(
        object? raw,
        IFormatProvider? provider,
        out TSelf? result,
        out IReadOnlyList<string> errors
    )
    {
        // A blank cell means "not filled in", which is the caller's business rather than a violation: a nullable column keeps
        // the property null, and a required one is reported by the edit model's own required check. A type whose notation
        // writes one of its values as a blank claims it through TryConvertAbsentInput - or declaratively through a
        // [DeclaredInstance(ClaimsAbsent = true)] field, consulted after the hook. The hook consult goes through TSelf so
        // it is honored no matter how this method is called (the same reason TryConvertCustomInput below goes through TSelf).
        if (raw is null or DBNull || (raw is string empty && empty.Length == 0))
        {
            if (TSelf.TryConvertAbsentInput(provider, out var absent) && absent is not null)
            {
                result = absent;
            }
            else if (DeclaredInstanceRegistry<TSelf, TValue>.TryGetAbsentInstance(out var claimed))
            {
                result = claimed;
            }
            else
            {
                result = null;
            }

            errors = Array.Empty<string>();
            return true;
        }

        // A shape the type accepts of its own (a name for an enumeration-like type, say) wins over the ordinary conversion.
        if (TSelf.TryConvertCustomInput(raw, provider, out var custom) && custom is not null)
        {
            result = custom;
            errors = Array.Empty<string>();
            return true;
        }

        // A declared input notation ([DeclaredInstance(InputText = ...)]) is the declarative counterpart of the hook
        // above: an exact ordinal match on a string input returns the declared instance, ahead of the ordinary conversion.
        if (raw is string text && DeclaredInstanceRegistry<TSelf, TValue>.TryGetForInput(text, out var notation))
        {
            result = notation;
            errors = Array.Empty<string>();
            return true;
        }

        object converted;

        try
        {
            converted = RawValueConverter.ConvertInput(raw, typeof(TValue), provider);
        }
        catch (Exception ex)
            when (ex is InvalidCastException
                or FormatException
                or OverflowException
                or ArgumentException
            )
        {
            result = null;
            errors = new[] { ValueObjectValidationMessages.InputNotConvertible(TSelf.DisplayName, raw) };
            return false;
        }

        return TSelf.TryCreate((TValue)converted, out result, out errors);
    }

    /// <summary>Converts a value from outside the model and creates the value object from it, using the invariant culture.</summary>
    public static bool TryCreateFrom(object? raw, out TSelf? result, out IReadOnlyList<string> errors) =>
        TSelf.TryCreateFrom(raw, null, out result, out errors);

    /// <summary>Converts a value from outside the model and creates the value object from it (throws ValueObjectValidationException on violation; an absent value returns null unless claimed through <see cref="IValueObject{TSelf}.TryConvertAbsentInput"/> or a ClaimsAbsent declared instance).</summary>
    /// <param name="raw">The value read from the source.</param>
    /// <param name="provider">The culture the text is written in; <c>null</c> uses the invariant culture.</param>
    /// <exception cref="ValueObjectValidationException">The value could not be converted, or failed validation.</exception>
    public static TSelf? CreateFrom(object? raw, IFormatProvider? provider)
    {
        if (TSelf.TryCreateFrom(raw, provider, out var result, out var errors))
        {
            return result;
        }

        throw new ValueObjectValidationException(typeof(TSelf), errors);
    }

    /// <summary>Converts a value from outside the model and creates the value object from it, using the invariant culture.</summary>
    public static TSelf? CreateFrom(object? raw) => TSelf.CreateFrom(raw, null);

    /// <summary>Gets the underlying value as an object (opens the raw value for SQL binding and similar).</summary>
    object? IValueObjectCore.UnderlyingValue => Value;

    /// <summary>Gets the string used for display (defaults to ToString()). A concrete value object's partial class can override it to change the format.</summary>
    public virtual string DisplayValue => ToString();

    /// <summary>Value-based equality with another instance of the same value object type (compared through <see cref="EqualityComparer{T}.Default"/>, so a struct value is not boxed).</summary>
    /// <remarks>
    /// Implementing <see cref="IEquatable{T}"/> is what lets <see cref="EqualityComparer{T}.Default"/> compare value objects
    /// by value directly. Without it the default comparer falls back to the object-based one, which reaches equality only
    /// through <see cref="Equals(object?)"/> and boxes a struct-valued argument on the way; every dictionary and hash-set
    /// lookup keyed by a value object goes through that comparer. A value object whose value is an array needs
    /// element-by-element comparison and overrides this — the binary value object base does, through
    /// <see cref="ValueObjectBinaryOperations"/>.
    /// </remarks>
    public virtual bool Equals(TSelf? other) =>
        other is not null && EqualityComparer<TValue>.Default.Equals(Value, other.Value);

    /// <summary>Value-based equality (delegates to the typed overload; anything that is not this value object type is unequal).</summary>
    public override bool Equals(object? obj) => obj is TSelf other && Equals(other);

    /// <summary>Value-based hash code (computed through <see cref="EqualityComparer{T}.Default"/>, so a struct value is not boxed).</summary>
    public override int GetHashCode() =>
        Value is null ? 0 : EqualityComparer<TValue>.Default.GetHashCode(Value);

    /// <summary>Value-based equality operator.</summary>
    public static bool operator ==(
        ValueObjectBaseCore<TSelf, TValue>? left,
        ValueObjectBaseCore<TSelf, TValue>? right
    ) => left is null ? right is null : left.Equals(right);

    /// <summary>Value-based inequality operator.</summary>
    public static bool operator !=(
        ValueObjectBaseCore<TSelf, TValue>? left,
        ValueObjectBaseCore<TSelf, TValue>? right
    ) => !(left == right);

    /// <summary>Returns the string representation of the underlying value.</summary>
    public override string ToString() => Value?.ToString() ?? string.Empty;

    /// <summary>Formats the underlying value with the given format string, using the current culture.</summary>
    /// <param name="format">The format string for the underlying value (for example "N2" on a decimal, "yyyy/MM/dd" on a date).</param>
    public string ToString(string? format) => ToString(format, null);

    /// <summary>Formats the underlying value with the given format string and culture.</summary>
    /// <remarks>
    /// Because the value object implements <see cref="IFormattable"/>, a format specifier in string interpolation,
    /// <see cref="string.Format(string, object?)"/>, or a WPF binding's StringFormat reaches the underlying value through
    /// this method. Without a format string the result is always <see cref="ToString()"/> (so an override of
    /// <see cref="ToString()"/> also governs unformatted interpolation and composite formatting, and the format provider
    /// is not consulted). The same applies when the underlying value does not implement <see cref="IFormattable"/>
    /// (a string, a byte array, a bool): the format is ignored, which is what composite formatting does for any such value.
    /// <see cref="DisplayValue"/> is the type's own display form; this method renders the format the caller asks for.
    /// </remarks>
    /// <param name="format">The format string for the underlying value.</param>
    /// <param name="formatProvider">The culture to format with; null uses the current culture.</param>
    public string ToString(string? format, IFormatProvider? formatProvider) =>
        !string.IsNullOrEmpty(format) && Value is IFormattable formattable
            ? formattable.ToString(format, formatProvider)
            : ToString();
}

/// <summary>Comparison bodies shared by the ordered, string and GUID-key value object bases.</summary>
public static class ValueObjectComparisons
{
    /// <summary>Compares a value object with an arbitrary object, for the non-generic <see cref="IComparable"/> surface.</summary>
    /// <remarks>
    /// A null object sorts first, an object of the same value object type is handed to the typed comparison, and anything
    /// else is a programming error rather than an ordering: sorting a list that mixes value object types would otherwise
    /// produce an arbitrary order instead of failing.
    /// </remarks>
    /// <param name="self">The value object the comparison starts from.</param>
    /// <param name="obj">The object to compare with.</param>
    /// <exception cref="ArgumentException"><paramref name="obj"/> is not of type <typeparamref name="TSelf"/>.</exception>
    public static int CompareToObject<TSelf>(IComparable<TSelf> self, object? obj)
        where TSelf : class =>
        obj is null ? 1
        : obj is TSelf other ? self.CompareTo(other)
        : throw new ArgumentException(
            $"{obj.GetType().Name} cannot be compared with {typeof(TSelf).Name}.",
            nameof(obj)
        );

    /// <summary>Orders two operands by their underlying values, treating null as the smallest value (two nulls are equal).</summary>
    /// <remarks>
    /// This is the body behind the ordering operators, which - unlike <see cref="IComparable{T}.CompareTo"/> - can be
    /// handed a null on either side.
    /// </remarks>
    public static int CompareOrdered<TSelf, TValue>(
        ValueObjectBaseCore<TSelf, TValue>? left,
        ValueObjectBaseCore<TSelf, TValue>? right
    )
        where TSelf : ValueObjectBaseCore<TSelf, TValue>, IValueObject<TSelf, TValue>
        where TValue : IComparable<TValue> =>
        left is null ? (right is null ? 0 : -1)
        : right is null ? 1
        : left.Value.CompareTo(right.Value);
}

/// <summary>Equality and hashing over a byte array, as a binary value object defines them.</summary>
public static class ValueObjectBinaryOperations
{
    /// <summary>Compares two arrays element by element (reference equality would make two equal blobs differ); two nulls are equal.</summary>
    /// <remarks>The comparison runs over spans, which compares whole machine words at a time instead of one element at a time — worth having on values that are blob-sized by definition.</remarks>
    public static bool AreEqual(byte[]? left, byte[]? right)
    {
        if (left is null || right is null)
        {
            return left is null && right is null;
        }

        return left.AsSpan().SequenceEqual(right);
    }

    /// <summary>Computes a hash code from every byte, matching <see cref="AreEqual"/>.</summary>
    /// <remarks>
    /// <see cref="HashCode.AddBytes(ReadOnlySpan{byte})"/> mixes in the whole array. The structural comparer used before it
    /// hashes only the last eight elements, so two blobs sharing a tail landed in the same bucket however much of their
    /// content differed — exactly the shape a binary value object tends to have when it wraps a versioned or padded payload.
    /// </remarks>
    public static int ComputeHashCode(byte[]? value)
    {
        if (value is null)
        {
            return 0;
        }

        var hash = new HashCode();
        hash.AddBytes(value);
        return hash.ToHashCode();
    }
}

/// <summary>Converter that reads and writes a value object as its underlying (raw) value in JSON.</summary>
public sealed class ValueObjectJsonConverter<TVo, TValue> : JsonConverter<TVo>
    where TVo : class, IValueObject<TVo, TValue>
{
    /// <summary>Reads the raw value and restores the value object via Create.</summary>
    public override TVo? Read(
        ref Utf8JsonReader reader,
        Type typeToConvert,
        JsonSerializerOptions options
    )
    {
        var value = JsonSerializer.Deserialize<TValue>(ref reader, options);
        return value is null ? null : TVo.Create(value);
    }

    /// <summary>Writes the underlying (raw) value.</summary>
    public override void Write(Utf8JsonWriter writer, TVo value, JsonSerializerOptions options) =>
        JsonSerializer.Serialize(writer, value.Value, options);
}

/// <summary>Factory that applies the generic converter to types implementing IValueObject&lt;,&gt;.</summary>
public sealed class ValueObjectJsonConverterFactory : JsonConverterFactory
{
    /// <summary>Returns whether the type is a value object type.</summary>
    public override bool CanConvert(Type typeToConvert) =>
        Array.Exists(
            typeToConvert.GetInterfaces(),
            i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IValueObject<,>)
        );

    /// <summary>Resolves the target type's TValue and creates a closed converter.</summary>
    public override JsonConverter CreateConverter(Type typeToConvert, JsonSerializerOptions options)
    {
        var iface = Array.Find(
            typeToConvert.GetInterfaces(),
            i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IValueObject<,>)
        )!;
        var valueType = iface.GetGenericArguments()[1];
        var converterType = typeof(ValueObjectJsonConverter<,>).MakeGenericType(
            typeToConvert,
            valueType
        );
        return (JsonConverter)Activator.CreateInstance(converterType)!;
    }
}

/// <summary>Automatic validation messages for value objects (defaults shared by all VOs). Replacing them at app startup applies to every VO.</summary>
/// <remarks>
/// <para>
/// Every message takes the value object's display name as its first argument, so one replacement covers both the wording
/// for every type and the wording for one type in particular - compare against that type's own <c>DisplayName</c> and let
/// the rest fall through:
/// <c>ValueObjectValidationMessages.ValueRequired = name =&gt; name == NameValue.DisplayName ? "..." : "...";</c>.
/// Naming the type keeps the comparison compiling against the generated code, so a column that is renamed away shows up as
/// a build error rather than as a message that quietly stops matching.
/// </para>
/// <para>
/// The default wording does not spell the display name out, because a value object's violation is normally shown next to
/// the field it belongs to; a replacement that needs the name has it in hand.
/// </para>
/// </remarks>
public static class ValueObjectValidationMessages
{
    /// <summary>Message for exceeding the maximum length (arguments: display name, maximum length, current character count).</summary>
    public static Func<string, int, int, string> MaxLengthExceeded { get; set; } =
        (_, maxLength, actualLength) =>
            $"Enter at most {maxLength} characters. (currently {actualLength} characters)";

    /// <summary>Message for exceeding the number of decimal places (arguments: display name, allowed scale).</summary>
    public static Func<string, int, string> ScaleExceeded { get; set; } =
        (_, scale) => $"Enter at most {scale} digits after the decimal point.";

    /// <summary>Message for exceeding the number of integer digits (arguments: display name, allowed integer digits).</summary>
    public static Func<string, int, string> PrecisionExceeded { get; set; } =
        (_, maxIntegralDigits) => $"Enter at most {maxIntegralDigits} digits in the integer part.";

    /// <summary>Message for a null value passed to Create/TryCreate (argument: display name). A value object never wraps null; keep the property itself null for nullable columns.</summary>
    public static Func<string, string> ValueRequired { get; set; } = _ => "A value is required.";

    /// <summary>Message for exceeding the number of digits of an integer (arguments: display name, allowed digit count).</summary>
    public static Func<string, int, string> DigitsExceeded { get; set; } =
        (_, maxDigits) => $"Enter at most {maxDigits} digits.";

    /// <summary>Message for a value outside the allowed range (arguments: display name, minimum, maximum; both bounds are allowed).</summary>
    public static Func<string, object, object, string> OutOfRange { get; set; } =
        (_, minimum, maximum) => $"Enter a value between {minimum} and {maximum}.";

    /// <summary>Message for a character outside the allowed set (arguments: display name, the extra symbols allowed, empty when none are).</summary>
    public static Func<string, string, string> InvalidCharacters { get; set; } =
        (_, allowedSymbols) =>
            allowedSymbols.Length == 0
                ? "Enter ASCII letters and digits only."
                : $"Enter ASCII letters, digits, and any of \"{allowedSymbols}\" only.";

    /// <summary>Message for a value that is not shaped like an email address (argument: display name).</summary>
    public static Func<string, string> InvalidEmailAddress { get; set; } =
        _ => "Enter a valid email address.";

    /// <summary>Message for a value from outside the model that could not be converted to the underlying type (arguments: display name, the value as read).</summary>
    public static Func<string, object, string> InputNotConvertible { get; set; } =
        (displayName, raw) => $"'{raw}' is not a valid {displayName}.";

    /// <summary>Message for a value outside a [DeclaredInstance] set (arguments: display name, the rejected value).</summary>
    public static Func<string, object, string> ValueNotDeclared { get; set; } =
        (displayName, value) => $"'{value}' is not a defined {displayName}.";
}

/// <summary>The rule every value object over a reference-typed value runs before the rest.</summary>
public static class ValueObjectRules
{
    /// <summary>Reports a null value as a violation, and tells the caller whether the rules that follow can run at all.</summary>
    /// <remarks>
    /// A value object never wraps null - a nullable column keeps the property itself null - so a null input is reported as
    /// a validation error rather than as an exception thrown out of the next rule. A false result means "stop here":
    /// every rule after this one dereferences the value.
    /// </remarks>
    /// <param name="value">The value being validated.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    /// <returns>True when the value is present; false when it was null and the violation was added.</returns>
    public static bool ValidateRequired<TValue>(
        TValue? value,
        string displayName,
        ref List<string>? errors
    )
        where TValue : class
    {
        if (value is not null)
        {
            return true;
        }

        (errors ??= new List<string>()).Add(
            ValueObjectValidationMessages.ValueRequired(displayName)
        );
        return false;
    }
}

/// <summary>Validation rules for string values: the maximum length a generated value object enforces, plus rules to call from <c>OnValidate</c>.</summary>
/// <remarks>
/// Each rule takes the error list by reference and possibly unallocated, and allocates it only when it has a violation to
/// add, so a value that passes every rule allocates nothing at all.
/// </remarks>
public static class ValueObjectStringRules
{
    /// <summary>Rejects a value longer than <paramref name="maxLength"/> characters.</summary>
    /// <param name="value">The value being validated.</param>
    /// <param name="maxLength">The greatest number of characters allowed.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void ValidateMaxLength(
        string value,
        int maxLength,
        string displayName,
        ref List<string>? errors
    )
    {
        if (value.Length > maxLength)
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.MaxLengthExceeded(
                    displayName,
                    maxLength,
                    value.Length
                )
            );
        }
    }

    /// <summary>Rejects any character that is neither an ASCII letter or digit nor one of <paramref name="allowedSymbols"/>.</summary>
    /// <remarks>
    /// The set is ASCII on purpose: a full-width letter or digit is rejected, which is what a code or an identifier column
    /// normally wants. At most one violation is added however many characters offend, because the message names the rule
    /// rather than the character.
    /// </remarks>
    /// <param name="value">The value being validated.</param>
    /// <param name="allowedSymbols">Extra characters to allow; an empty string allows no symbols at all.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void ValidateAsciiAlphanumeric(
        string value,
        string allowedSymbols,
        string displayName,
        ref List<string>? errors
    )
    {
        foreach (var character in value)
        {
            if (char.IsAsciiLetterOrDigit(character) || allowedSymbols.Contains(character))
            {
                continue;
            }

            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.InvalidCharacters(displayName, allowedSymbols)
            );
            return;
        }
    }

    /// <summary>Rejects a value that is not shaped like an email address: exactly one '@', a non-empty part on each side of it, and no whitespace anywhere.</summary>
    /// <remarks>
    /// This is a practical minimum rather than RFC 5322. The full grammar accepts quoted local parts, comments and address
    /// literals that no application wants stored in a column, and turning an address away is worse than letting an odd one
    /// through - deliverability is settled by sending mail, not by a pattern. <see cref="System.Net.Mail.MailAddress"/> is
    /// not used for the same reason it looks tempting: it also parses the display-name form ("Name &lt;a@b&gt;"), so a
    /// whole header line would pass as an address.
    /// </remarks>
    /// <param name="value">The value being validated.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void ValidateEmailAddress(
        string value,
        string displayName,
        ref List<string>? errors
    )
    {
        if (!IsEmailAddress(value))
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.InvalidEmailAddress(displayName)
            );
        }
    }

    /// <summary>Returns whether the text has the shape <see cref="ValidateEmailAddress"/> accepts.</summary>
    private static bool IsEmailAddress(string value)
    {
        var at = value.IndexOf('@');

        if (at <= 0 || at == value.Length - 1 || at != value.LastIndexOf('@'))
        {
            return false;
        }

        foreach (var character in value)
        {
            if (char.IsWhiteSpace(character))
            {
                return false;
            }
        }

        return true;
    }
}

/// <summary>Validation rules for numeric values, to call from a value object's <c>OnValidate</c>.</summary>
/// <remarks>
/// Each rule takes the error list by reference and possibly unallocated, and allocates it only when it has a violation to
/// add, so a value that passes every rule allocates nothing at all.
/// </remarks>
public static class ValueObjectNumberRules
{
    /// <summary>Rejects an integer written with more than <paramref name="maxDigits"/> digits.</summary>
    /// <remarks>The sign does not count, and neither do leading zeros, which an integer does not carry; zero is one digit.</remarks>
    /// <param name="value">The value being validated (a narrower integer type widens to it).</param>
    /// <param name="maxDigits">The greatest number of digits allowed.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void ValidateMaxDigits(
        long value,
        int maxDigits,
        string displayName,
        ref List<string>? errors
    )
    {
        if (CountDigits(value) > maxDigits)
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.DigitsExceeded(displayName, maxDigits)
            );
        }
    }

    /// <summary>Rejects a value outside the closed interval from <paramref name="minimum"/> to <paramref name="maximum"/> (both bounds are allowed).</summary>
    /// <param name="value">The value being validated.</param>
    /// <param name="minimum">The smallest value allowed.</param>
    /// <param name="maximum">The greatest value allowed.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void ValidateRange<T>(
        T value,
        T minimum,
        T maximum,
        string displayName,
        ref List<string>? errors
    )
        where T : IComparable<T>
    {
        if (value.CompareTo(minimum) < 0 || value.CompareTo(maximum) > 0)
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.OutOfRange(displayName, minimum, maximum)
            );
        }
    }

    /// <summary>Counts the digits an integer is written with, ignoring the sign.</summary>
    private static int CountDigits(long value)
    {
        // long.MinValue has no positive counterpart, so negating it would overflow; its digit count is a constant.
        if (value == long.MinValue)
        {
            return 19;
        }

        var remaining = value < 0 ? -value : value;
        var digits = 1;

        while (remaining >= 10)
        {
            remaining /= 10;
            digits++;
        }

        return digits;
    }
}

/// <summary>Validation rules for decimal values: the digit counts a generated value object enforces from the column's precision and scale.</summary>
/// <remarks>
/// Each rule takes the error list by reference and possibly unallocated, and allocates it only when it has a violation to
/// add, so a value that passes every rule allocates nothing at all.
/// </remarks>
public static class ValueObjectDecimalRules
{
    /// <summary>Powers of ten, so the integer part is checked with one comparison instead of a division per digit.</summary>
    /// <remarks>
    /// A decimal holds at most 29 significant digits, so the table ends at 10^28 and a limit at least that wide can never
    /// be exceeded.
    /// </remarks>
    private static readonly decimal[] PowersOfTen =
    {
        1m,
        1e1m,
        1e2m,
        1e3m,
        1e4m,
        1e5m,
        1e6m,
        1e7m,
        1e8m,
        1e9m,
        1e10m,
        1e11m,
        1e12m,
        1e13m,
        1e14m,
        1e15m,
        1e16m,
        1e17m,
        1e18m,
        1e19m,
        1e20m,
        1e21m,
        1e22m,
        1e23m,
        1e24m,
        1e25m,
        1e26m,
        1e27m,
        1e28m,
    };

    /// <summary>Validates the digit counts of a decimal (does not round; rejects overflow). Trailing zeros count toward the scale.</summary>
    /// <param name="value">The value being validated.</param>
    /// <param name="precision">The column's total number of digits.</param>
    /// <param name="scale">The column's number of decimal places; the integer part may hold <c>precision - scale</c> digits.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void Validate(
        decimal value,
        int precision,
        int scale,
        string displayName,
        ref List<string>? errors
    )
    {
        // decimal.Scale states the number of decimal places directly; reading it out of decimal.GetBits meant
        // allocating a four-element int array on every single validation just to shift one of the words.
        if (value.Scale > scale)
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.ScaleExceeded(displayName, scale)
            );
        }

        var maxIntegralDigits = precision - scale;
        var integral = Math.Truncate(Math.Abs(value));

        if (
            maxIntegralDigits < 0
            || (
                maxIntegralDigits < PowersOfTen.Length
                && integral >= PowersOfTen[maxIntegralDigits]
            )
        )
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.PrecisionExceeded(displayName, maxIntegralDigits)
            );
        }
    }
}

/// <summary>Marker implemented by every value object. Adding an interface or a member to a partial declaration of this type reaches all of them at once.</summary>
public partial interface IValueObject : IValueObjectCore { }

/// <summary>Base of every value object, and the extension point that reaches all of them: a member added to a partial declaration of this class is available on every value object whatever its value shape. The shaped bases below all derive from it, and a value object whose underlying type has no shaped base of its own (a Guid or an sbyte, say) derives from it directly.</summary>
/// <typeparam name="TSelf">The concrete value object type deriving from this class.</typeparam>
/// <typeparam name="TValue">The underlying value type.</typeparam>
public abstract partial class ValueObjectBase<TSelf, TValue>
    : ValueObjectBaseCore<TSelf, TValue>,
        IValueObject
    where TSelf : ValueObjectBase<TSelf, TValue>, IValueObject<TSelf, TValue>
{
    /// <summary>Initializes with an already-validated value.</summary>
    protected ValueObjectBase(TValue value)
        : base(value) { }
}

/// <summary>Base of every orderable value object (numeric and date/time types), and the extension point for them. Provides comparison operators and CompareTo.</summary>
/// <typeparam name="TSelf">The concrete value object type deriving from this class.</typeparam>
/// <typeparam name="TValue">The underlying value type.</typeparam>
public abstract partial class ValueObjectOrderedBase<TSelf, TValue>
    : ValueObjectBase<TSelf, TValue>,
        IComparable<TSelf>,
        IComparable
    where TSelf : ValueObjectOrderedBase<TSelf, TValue>, IValueObject<TSelf, TValue>
    where TValue : IComparable<TValue>
{
    /// <summary>Initializes with an already-validated value.</summary>
    protected ValueObjectOrderedBase(TValue value)
        : base(value) { }

    /// <summary>Compares the underlying values.</summary>
    public int CompareTo(TSelf? other) => other is null ? 1 : Value.CompareTo(other.Value);

    /// <summary>Non-generic comparison (a type mismatch throws).</summary>
    int IComparable.CompareTo(object? obj) =>
        ValueObjectComparisons.CompareToObject<TSelf>(this, obj);

    /// <summary>Less-than.</summary>
    public static bool operator <(
        ValueObjectOrderedBase<TSelf, TValue>? left,
        ValueObjectOrderedBase<TSelf, TValue>? right
    ) => ValueObjectComparisons.CompareOrdered(left, right) < 0;

    /// <summary>Greater-than.</summary>
    public static bool operator >(
        ValueObjectOrderedBase<TSelf, TValue>? left,
        ValueObjectOrderedBase<TSelf, TValue>? right
    ) => ValueObjectComparisons.CompareOrdered(left, right) > 0;

    /// <summary>Less-than-or-equal.</summary>
    public static bool operator <=(
        ValueObjectOrderedBase<TSelf, TValue>? left,
        ValueObjectOrderedBase<TSelf, TValue>? right
    ) => ValueObjectComparisons.CompareOrdered(left, right) <= 0;

    /// <summary>Greater-than-or-equal.</summary>
    public static bool operator >=(
        ValueObjectOrderedBase<TSelf, TValue>? left,
        ValueObjectOrderedBase<TSelf, TValue>? right
    ) => ValueObjectComparisons.CompareOrdered(left, right) >= 0;
}

/// <summary>Base of every string value object, and the extension point for them. Provides substring-match methods and ordinal comparison (does not add ordering operators).</summary>
/// <typeparam name="TSelf">The concrete value object type deriving from this class.</typeparam>
public abstract partial class ValueObjectStringBase<TSelf>
    : ValueObjectBase<TSelf, string>,
        IStringMatchValueObject<TSelf>,
        IComparable<TSelf>,
        IComparable
    where TSelf : ValueObjectStringBase<TSelf>, IValueObject<TSelf, string>
{
    /// <summary>Initializes with an already-validated value.</summary>
    protected ValueObjectStringBase(string value)
        : base(value) { }

    /// <summary>Returns whether the value contains the specified string.</summary>
    /// <remarks>Throws <see cref="ArgumentNullException"/> when value is null (the same contract as <c>string.Contains</c>).</remarks>
    public bool Contains(string value)
    {
        ArgumentNullException.ThrowIfNull(value);
        return Value.Contains(value, StringComparison.Ordinal);
    }

    /// <summary>Returns whether the value starts with the specified string.</summary>
    /// <remarks>Throws <see cref="ArgumentNullException"/> when value is null (the same contract as <c>string.StartsWith</c>).</remarks>
    public bool StartsWith(string value)
    {
        ArgumentNullException.ThrowIfNull(value);
        return Value.StartsWith(value, StringComparison.Ordinal);
    }

    /// <summary>Returns whether the value ends with the specified string.</summary>
    /// <remarks>Throws <see cref="ArgumentNullException"/> when value is null (the same contract as <c>string.EndsWith</c>).</remarks>
    public bool EndsWith(string value)
    {
        ArgumentNullException.ThrowIfNull(value);
        return Value.EndsWith(value, StringComparison.Ordinal);
    }

    /// <summary>Returns whether the value contains another value object's value.</summary>
    /// <remarks>Throws <see cref="ArgumentNullException"/> when value is null (the same contract as the string overload).</remarks>
    public bool Contains(TSelf value)
    {
        ArgumentNullException.ThrowIfNull(value);
        return Contains(value.Value);
    }

    /// <summary>Returns whether the value starts with another value object's value.</summary>
    /// <remarks>Throws <see cref="ArgumentNullException"/> when value is null (the same contract as the string overload).</remarks>
    public bool StartsWith(TSelf value)
    {
        ArgumentNullException.ThrowIfNull(value);
        return StartsWith(value.Value);
    }

    /// <summary>Returns whether the value ends with another value object's value.</summary>
    /// <remarks>Throws <see cref="ArgumentNullException"/> when value is null (the same contract as the string overload).</remarks>
    public bool EndsWith(TSelf value)
    {
        ArgumentNullException.ThrowIfNull(value);
        return EndsWith(value.Value);
    }

    /// <summary>Compares ordinally.</summary>
    public int CompareTo(TSelf? other) =>
        other is null ? 1 : string.CompareOrdinal(Value, other.Value);

    /// <summary>Non-generic comparison (a type mismatch throws).</summary>
    int IComparable.CompareTo(object? obj) =>
        ValueObjectComparisons.CompareToObject<TSelf>(this, obj);
}

/// <summary>Base of every bool value object, and the extension point for them. Provides True/False factories and truth checks (has no ordered comparison).</summary>
/// <typeparam name="TSelf">The concrete value object type deriving from this class.</typeparam>
public abstract partial class ValueObjectBooleanBase<TSelf> : ValueObjectBase<TSelf, bool>
    where TSelf : ValueObjectBooleanBase<TSelf>, IValueObject<TSelf, bool>
{
    /// <summary>Initializes with an already-validated value.</summary>
    protected ValueObjectBooleanBase(bool value)
        : base(value) { }

    /// <summary>Creates the value object from the true value.</summary>
    public static TSelf True => TSelf.Create(true);

    /// <summary>Creates the value object from the false value.</summary>
    public static TSelf False => TSelf.Create(false);

    /// <summary>Gets whether the value is true.</summary>
    public bool IsTrue => Value;

    /// <summary>Gets whether the value is false.</summary>
    public bool IsFalse => !Value;
}

/// <summary>Base of every DateTime value object, and the extension point for them. Provides Now/Today factories.</summary>
/// <typeparam name="TSelf">The concrete value object type deriving from this class.</typeparam>
public abstract partial class ValueObjectDateTimeBase<TSelf>
    : ValueObjectOrderedBase<TSelf, DateTime>
    where TSelf : ValueObjectDateTimeBase<TSelf>, IValueObject<TSelf, DateTime>
{
    /// <summary>Initializes with an already-validated value.</summary>
    protected ValueObjectDateTimeBase(DateTime value)
        : base(value) { }

    /// <summary>Creates the value object from the current date and time.</summary>
    public static TSelf Now => TSelf.Create(DateTime.Now);

    /// <summary>Creates the value object from today (time 0:00).</summary>
    public static TSelf Today => TSelf.Create(DateTime.Today);
}

/// <summary>Base of every byte[] value object, and the extension point for them. ToString returns Base64, and equality compares the arrays element by element.</summary>
/// <remarks>
/// The wrapped array is NOT defensively copied: the value object holds (and exposes through Value) the very array it was
/// created with, because copying would double the allocation of every binary column read from the database. Treat the array
/// as frozen after Create — mutating it afterwards silently changes the value object's equality, hash code, and ToString.
/// </remarks>
/// <typeparam name="TSelf">The concrete value object type deriving from this class.</typeparam>
public abstract partial class ValueObjectBinaryBase<TSelf> : ValueObjectBase<TSelf, byte[]>
    where TSelf : ValueObjectBinaryBase<TSelf>, IValueObject<TSelf, byte[]>
{
    /// <summary>Initializes with an already-validated value.</summary>
