    static bool IValueObject<OrderIdValue>.TryConvertAbsentInput(IFormatProvider? provider, out OrderIdValue? result)
    {
        OrderIdValue? absent = null;
        ConvertAbsentInput(provider, ref absent);
        result = absent;
        return absent is not null;
    }

    /// <summary>Absent input (null, DBNull, or an empty string) for TryCreateFrom / CreateFrom - a flag whose blank cell means a value of its own, say (partial; an absent input falls to a ClaimsAbsent declared instance or the ordinary null result when not implemented). Set result to claim the absent input; leave it null and the call succeeds with a null value object. This hook applies to TryCreateFrom / CreateFrom only - an edit model's blank input and a database NULL are unaffected. Never call TryCreateFrom / CreateFrom from inside (they consult this hook and the call would recurse), and do not throw - TryCreateFrom reports failures through its return value, and an exception here rides straight through that contract.</summary>
    static partial void ConvertAbsentInput(IFormatProvider? provider, ref OrderIdValue? result);

    /// <summary>Gets the display name of this value object (used in error messages and similar). Defaults to the column description, or the property name when unset. Replace it through GeneratedDisplayNames.Resolve, which resolves every generated display name and can switch on the member name.</summary>
    public static string DisplayName =>
        GeneratedDisplayNames.Resolve("OrderId", null);
}

/// <summary>Converts a raw value read from the database into a target CLR type, including the types <see cref="Convert.ChangeType(object, Type, IFormatProvider)"/> cannot reach on its own.</summary>
/// <remarks>
/// <para>
/// <c>Convert.ChangeType</c> only converts types that implement <see cref="IConvertible"/>. <see cref="TimeSpan"/>,
/// <see cref="Guid"/>, <see cref="DateTimeOffset"/>, <see cref="DateOnly"/> and <see cref="TimeOnly"/> do not, so a driver
/// that hands such a column back as text makes it throw <see cref="InvalidCastException"/> - which is what SQLite does for
/// every one of them, since it stores them as TEXT. Those types are parsed from the string instead, with the invariant culture.
/// SQL Server returns them already typed, so they take the pass-through above and never reach the parsing.
/// </para>
/// <para>
/// This is the single conversion shared by value object rewrapping, raw SQL scalars and raw SQL projection properties. The
/// SQLite engine's own column coercion (<c>EntitySaveMetadata.CoerceScalar</c>) accepts the same stored formats for the same
/// types, so a value object column and a plain column read the same text the same way.
/// </para>
/// <para>
/// <see cref="ConvertInput"/> is the same conversion for a value that did not come from a database - a spreadsheet cell, a CSV
/// field, a form field - where the culture belongs to the caller and numeric text carries the group separators a person typed.
/// Both entry points share one body, so the list of types they can reach cannot drift apart.
/// </para>
/// </remarks>
internal static class RawValueConverter
{
    /// <summary>Converts the raw value to the target type (a nullable target is judged by its underlying type); a value already of that type is returned as is.</summary>
    /// <param name="raw">The value the driver returned (never <c>null</c>: the callers map null and <c>DBNull</c> before this point).</param>
    /// <param name="targetType">The type to convert to.</param>
    /// <exception cref="InvalidCastException">No conversion exists between the two types.</exception>
    /// <exception cref="FormatException">The text does not have the shape the target type requires.</exception>
    /// <exception cref="OverflowException">The value does not fit the target type.</exception>
    public static object ConvertRaw(object raw, Type targetType) =>
        ConvertCore(raw, targetType, CultureInfo.InvariantCulture, allowNumericGroupSeparators: false);

    /// <summary>Converts a value that came from outside the database - a spreadsheet cell, a CSV field, a form field - to the target type.</summary>
    /// <remarks>
    /// Two things separate this from <see cref="ConvertRaw"/>. The culture is the one the caller passes, because the text was
    /// written by a person or by an application that formatted it for one. And numeric text is parsed with group separators
    /// allowed, because a spreadsheet hands back "1,234" for a column formatted that way while
    /// <see cref="System.Convert.ChangeType(object, Type, IFormatProvider)"/> rejects it outright. An integral target still
    /// rejects a decimal point, so "1,234.5" does not quietly become an int.
    /// </remarks>
    /// <param name="raw">The value read from the source (never <c>null</c>: the callers map the empty cases before this point).</param>
    /// <param name="targetType">The type to convert to.</param>
    /// <param name="provider">The culture the text is written in; <c>null</c> uses the invariant culture.</param>
    /// <exception cref="InvalidCastException">No conversion exists between the two types.</exception>
    /// <exception cref="FormatException">The text does not have the shape the target type requires.</exception>
    /// <exception cref="OverflowException">The value does not fit the target type.</exception>
    public static object ConvertInput(object raw, Type targetType, IFormatProvider? provider) =>
        ConvertCore(raw, targetType, provider ?? CultureInfo.InvariantCulture, allowNumericGroupSeparators: true);

    /// <summary>Body shared by <see cref="ConvertRaw"/> and <see cref="ConvertInput"/>; the two differ only in the culture and in whether numeric text may carry group separators.</summary>
    private static object ConvertCore(
        object raw,
        Type targetType,
        IFormatProvider provider,
        bool allowNumericGroupSeparators
    )
    {
        var underlying = Nullable.GetUnderlyingType(targetType) ?? targetType;

        if (underlying.IsInstanceOfType(raw))
        {
            return raw;
        }

        // Text is the only shape these types can arrive in, and none of them implements IConvertible,
        // so leaving them to ChangeType would fail on every value rather than on a malformed one
        if (raw is string text && !typeof(IConvertible).IsAssignableFrom(underlying))
        {
            if (underlying == typeof(Guid))
            {
                return Guid.Parse(text);
            }

            if (underlying == typeof(TimeSpan))
            {
                return ParseTimeSpan(text, provider);
            }

            if (underlying == typeof(DateTimeOffset))
            {
                return DateTimeOffset.Parse(text, provider, System.Globalization.DateTimeStyles.RoundtripKind);
            }

            if (underlying == typeof(DateOnly))
            {
                return DateOnly.Parse(text, provider);
            }

            if (underlying == typeof(TimeOnly))
            {
                return TimeOnly.Parse(text, provider);
            }
        }

        if (allowNumericGroupSeparators && raw is string number && ParseNumber(number, underlying, provider) is { } parsed)
        {
            return parsed;
        }

        return Convert.ChangeType(raw, underlying, provider);
    }

    /// <summary>Parses numeric text with group separators allowed, or returns null when the target is not a number.</summary>
    /// <remarks>
    /// An integral target takes <see cref="NumberStyles.Integer"/> rather than <see cref="NumberStyles.Number"/> on purpose:
    /// the latter also allows a decimal point, which would let "1,234.5" through as an int. A fractional target keeps the
    /// exponent form that <c>ChangeType</c> would have accepted.
    /// </remarks>
    private static object? ParseNumber(string text, Type underlying, IFormatProvider provider)
    {
        const NumberStyles Integral = NumberStyles.Integer | NumberStyles.AllowThousands;
        const NumberStyles Fractional = NumberStyles.Float | NumberStyles.AllowThousands;

        return Type.GetTypeCode(underlying) switch
        {
            TypeCode.Byte => byte.Parse(text, Integral, provider),
            TypeCode.SByte => sbyte.Parse(text, Integral, provider),
            TypeCode.Int16 => short.Parse(text, Integral, provider),
            TypeCode.UInt16 => ushort.Parse(text, Integral, provider),
            TypeCode.Int32 => int.Parse(text, Integral, provider),
            TypeCode.UInt32 => uint.Parse(text, Integral, provider),
            TypeCode.Int64 => long.Parse(text, Integral, provider),
            TypeCode.UInt64 => ulong.Parse(text, Integral, provider),
            TypeCode.Single => float.Parse(text, Fractional, provider),
            TypeCode.Double => double.Parse(text, Fractional, provider),
            TypeCode.Decimal => decimal.Parse(text, Fractional, provider),
            _ => null,
        };
    }

    /// <summary>Parses a <see cref="TimeSpan"/> stored as text.</summary>
    /// <remarks>
    /// The round-trip format "c" ([-][d.]hh:mm:ss[.fffffff]) is what the SQLite provider writes, and it also accepts the
    /// forms that round-trip shorter values ("01:00:00", "1.02:03:04", "10:20:30.1234567"). The fallback covers text that
    /// something other than this library stored (a hand-written INSERT such as "1:2:3"), which is the same set the plain
    /// column path has always accepted, so both paths read the same rows.
    /// </remarks>
    private static TimeSpan ParseTimeSpan(string text, IFormatProvider provider) =>
        TimeSpan.TryParseExact(text, "c", CultureInfo.InvariantCulture, out var roundTripped)
            ? roundTripped
            : TimeSpan.Parse(text, provider);
}

/// <summary>Change state of an entity or EditModel.</summary>
public enum RowState
{
    /// <summary>Marked for insert (new).</summary>
    Added,

    /// <summary>Unchanged (already persisted).</summary>
    Unchanged,

    /// <summary>Marked for update.</summary>
    Updated,

    /// <summary>Marked for removal.</summary>
    Removed,
}

/// <summary>Base class that holds the change tracking state (RowState) of an entity.</summary>
public abstract class EntityBaseCore
{
    /// <summary>Change tracking state of this entity. Defaults to Unchanged; restoring from the database or JSON keeps it Unchanged.</summary>
    public RowState RowState { get; set; } = RowState.Unchanged;

    /// <summary>Gets whether this entity is marked for insert.</summary>
    public bool IsAdded => RowState == RowState.Added;

    /// <summary>Gets whether this entity is marked for update.</summary>
    public bool IsUpdated => RowState == RowState.Updated;

    /// <summary>Gets whether this entity is marked for removal.</summary>
    public bool IsRemoved => RowState == RowState.Removed;

    /// <summary>Gets whether this entity has any change (insert, update, or removal).</summary>
    public bool HasChanges => RowState != RowState.Unchanged;

    /// <summary>Display name of this entity (used for UI labels and so on). Returns <see cref="DefaultDisplayName"/>; substitute display names by replacing GeneratedDisplayNames.Resolve and branching on the class name it receives.</summary>
    public string DisplayName => DefaultDisplayName;

    /// <summary>Default display name. Resolved from the runtime class name through GeneratedDisplayNames.Resolve (no description); entities that carry a table description override this in the derived class.</summary>
    protected virtual string DefaultDisplayName => GeneratedDisplayNames.Resolve(GetType().Name, null);

    /// <summary>Marks this entity for insert (use when a directly constructed entity should be saved).</summary>
    /// <param name="includeChildren">
    /// <c>true</c> to mark the cascade children as well (the child-direction navigations a graph save follows, all the way
    /// down), so a freshly built aggregate can be marked in a single call. The default <c>false</c> marks this entity only.
    /// </param>
    /// <remarks>
    /// Only MarkAdded offers the cascading form. Marking a whole graph for update is ambiguous (the save would rewrite every
    /// row, including the ones nothing touched), and marking a whole graph for removal is what the graph save's
    /// <c>cascadeDelete</c> option already does from the root alone.
    /// </remarks>
    public void MarkAdded(bool includeChildren = false)
    {
        RowState = RowState.Added;

        if (!includeChildren)
        {
            return;
        }

        // Cascade navigations point at children only (parent references are excluded), so the traversal is a tree and terminates
        foreach (var child in EnumerateCascadeChildren())
        {
            child.MarkAdded(true);
        }
    }

    /// <summary>Caches the cascade navigation properties per type (the child-direction navigations a graph save follows).</summary>
    private static readonly ConcurrentDictionary<Type, PropertyInfo[]> _cascadeNavigationCache = new();

    /// <summary>Returns the cascade navigation properties of the given type (scanned once per type and cached).</summary>
    private static PropertyInfo[] GetCascadeNavigations(Type type) =>
        _cascadeNavigationCache.GetOrAdd(
            type,
            static resolvedType =>
                resolvedType
                    .GetProperties(BindingFlags.Public | BindingFlags.Instance)
                    .Where(property =>
                        property.GetCustomAttribute<NavigationReferenceAttribute>()
                            is { Cascade: true }
                    )
                    .ToArray()
        );

    /// <summary>Enumerates the children reachable through cascade navigations (single references and collections alike; nulls are skipped).</summary>
    /// <remarks>
    /// This is the one description of "which children a graph operation follows", and everything that has to walk the same
    /// shape - marking an aggregate, saving it, journaling it for a sync run - reads it from here rather than repeating the
    /// attribute scan. Cascade navigations point at children only (parent references are excluded), so the traversal is a
    /// tree and terminates.
    /// </remarks>
    public IEnumerable<EntityBaseCore> EnumerateCascadeChildren()
    {
        foreach (var navigation in GetCascadeNavigations(GetType()))
        {
            var value = navigation.GetValue(this);

            if (value is EntityBaseCore child)
            {
                yield return child;
            }
            else if (value is IEnumerable<EntityBaseCore> children)
            {
                foreach (var item in children)
                {
                    if (item is not null)
                    {
                        yield return item;
                    }
                }
            }
        }
    }

    /// <summary>Marks this entity for removal (it stays in the collection but is deleted on save).</summary>
    public void MarkRemoved() => RowState = RowState.Removed;

    /// <summary>Marks this entity as Unchanged (already persisted).</summary>
    public void MarkUnchanged() => RowState = RowState.Unchanged;

    /// <summary>Marks this entity for update only when it is currently Unchanged.</summary>
    public void MarkUpdated()
    {
        if (RowState == RowState.Unchanged)
        {
            RowState = RowState.Updated;
        }
    }

    // ---- Value comparison, hashing, and JSON output ----

    /// <summary>Caches the "value properties" per type (the public get/set properties carrying a <see cref="ColumnAttribute"/>).</summary>
    private static readonly ConcurrentDictionary<Type, PropertyInfo[]> _valuePropertyCache = new();

    /// <summary>Returns the value properties of the given type (scanned once per type and cached).</summary>
    /// <remarks>A property is a column only when it carries <see cref="ColumnAttribute"/>, which the generator puts on every column property. Anything else a partial declaration adds - navigations, RowState, and members added to the extension surface - is therefore not a column. Add <see cref="ColumnAttribute"/> with the name of a real column to opt a handwritten property in.</remarks>
    private static PropertyInfo[] GetValueProperties(Type type) =>
        _valuePropertyCache.GetOrAdd(
            type,
            static resolvedType =>
                resolvedType
                    .GetProperties(BindingFlags.Public | BindingFlags.Instance)
                    .Where(property =>
                        property.CanRead
                        && property.CanWrite
                        && Attribute.IsDefined(property, typeof(ColumnAttribute))
                    )
                    .ToArray()
        );

    /// <summary>Determines whether all column values match those of another entity (RowState and navigations are excluded from the comparison).</summary>
    /// <remarks>The comparison reads each column through reflection (the property list itself is cached per type). That is meant for change detection and assertions, not for a hot path — write the comparison out by hand where one is called for.</remarks>
    public bool HasSameValues(EntityBaseCore? other)
    {
        if (other is null)
        {
            return false;
        }

        if (ReferenceEquals(this, other))
        {
            return true;
        }

        var type = GetType();
        if (other.GetType() != type)
        {
            return false;
        }

        foreach (var property in GetValueProperties(type))
        {
            // Compare arrays such as byte[] structurally (element by element).
            if (
                !StructuralComparisons.StructuralEqualityComparer.Equals(
                    property.GetValue(this),
                    property.GetValue(other)
                )
            )
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>Returns a value-based hash code computed from the column values (RowState and navigations are excluded).</summary>
    /// <remarks>Two entities for which HasSameValues is true always return the same value. Since the object is mutable, do not modify it while using it as a dictionary key. Like HasSameValues, it reads the columns through reflection and is not meant for a hot path.</remarks>
    public int GetValueHashCode()
    {
        var type = GetType();
        var hash = new HashCode();
        hash.Add(type);
        foreach (var property in GetValueProperties(type))
        {
            var value = property.GetValue(this);
            // Use a structural hash for arrays such as byte[].
            hash.Add(
                value is null
                    ? 0
                    : StructuralComparisons.StructuralEqualityComparer.GetHashCode(value)
            );
        }

        return hash.ToHashCode();
    }

    /// <summary>Serialization options shared by JSON output (ToJson) and cloning (Clone). Reused so that type-metadata caching takes effect.</summary>
    /// <remarks>Only public get/set properties are included. Any accidental cycle is nulled out via IgnoreCycles to avoid exceptions (with the [JsonIgnore] configuration there is no cycle, so this is a no-op).</remarks>
    private static readonly JsonSerializerOptions _jsonOptions = new()
    {
        IgnoreReadOnlyProperties = true,
        ReferenceHandler = ReferenceHandler.IgnoreCycles,
        Converters = { new ValueObjectJsonConverterFactory() },
    };

    /// <summary>Options for indented output (writeIndented=true). Kept as a separate instance because WriteIndented cannot be changed after first use.</summary>
    private static readonly JsonSerializerOptions _jsonOptionsIndented = new()
    {
        IgnoreReadOnlyProperties = true,
        ReferenceHandler = ReferenceHandler.IgnoreCycles,
        WriteIndented = true,
        Converters = { new ValueObjectJsonConverterFactory() },
    };

    /// <summary>Serializes this entity to a JSON string (used for passing data to a web API and so on).</summary>
    /// <remarks>
    /// Only public get/set properties are included (get-only derived flags such as IsAdded are not emitted; RowState is emitted).
    /// Child navigations are included; parent-reference navigations carry [JsonIgnore] so no cycle occurs.
    /// </remarks>
    public string ToJson(bool writeIndented = false) =>
        JsonSerializer.Serialize(
            this,
            GetType(),
            writeIndented ? _jsonOptionsIndented : _jsonOptions
        );

    /// <summary>Creates a deep clone of this entity (via a JSON round-trip).</summary>
    /// <remarks>
    /// Values, RowState, and child navigations are copied. Parent-reference navigations are not restored because of [JsonIgnore] (the clone does not point to a parent).
    /// To insert it as a separate record, reassign the primary key or call MarkAdded() after cloning. The returned instance has the same concrete type as the original.
    /// </remarks>
    public EntityBaseCore Clone()
    {
        var type = GetType();
        var json = JsonSerializer.Serialize(this, type, _jsonOptions);
        return (EntityBaseCore)JsonSerializer.Deserialize(json, type, _jsonOptions)!;
    }
}

/// <summary>Resolves default display names for generated members (entities, edit model properties, and value objects). Replacing the resolver at app startup applies to every generated display name.</summary>
public static class GeneratedDisplayNames
{
    /// <summary>Resolves a display name from the member name and the column/table description (null when unset). The default prefers the description and falls back to the member name. Replace with (name, _) =&gt; name to ignore descriptions.</summary>
    public static Func<string, string?, string> Resolve { get; set; } =
        static (memberName, description) => description ?? memberName;
}

/// <summary>Base of every generated entity, and the extension point for them. Members added to a partial declaration of this type reach all of them at once.</summary>
public abstract partial class EntityBase : EntityBaseCore { }

